PAYOFF_BODY = r"""const n=years*12,r=rate/1200,m=PMT(bal,rate,n);
let b=bal,k=0,tot=0;
while(b>0.005&&k<n+600){const i=b*r;tot+=i;let p=m+extra-i;if(p>b)p=b;b-=p;k++;}
const base=m*n-bal,d=new Date();d.setMonth(d.getMonth()+k);
return [['Payoff time',Math.floor(k/12)+' years '+k%12+' months'],['Monthly payment (required)',M(m)],['Total interest with extra payments',M(tot)],['Interest saved',M(Math.max(base-tot,0))],['Months saved',Math.max(n-k,0)],['Payoff date',d.toLocaleDateString('en-US',{month:'long',year:'numeric'})]];"""

