  [("rev", "Revenue ($)", 120000), ("cogs", "Cost of goods ($)", 55000), ("opex", "Operating expenses ($)", 40000)],
  r"""const g=rev-cogs,n=g-opex;return [['Net profit',M(n)],['Gross profit',M(g)],['Gross margin',PCT(g/rev*100,1)],['Net margin',PCT(n/rev*100,1)]];""",
